import assert from "node:assert/strict";
import test from "node:test";
import { chromium } from "playwright";
import { observe } from "../src/jev-browser.ts";
import { runJev } from "../src/jev-run.ts";

test("post-action navigation read is recovered without repeating the click", async () => {
	const browser = await chromium.launch({ headless: true });
	try {
		const page = await browser.newPage();
		await page.setContent(
			"<button onclick=\"this.textContent='Opened'\">Open</button>",
		);
		const originalRead = page.evaluateHandle.bind(page);
		let invalidateNextRead = false;
		let failures = 0;
		page.evaluateHandle = (async (
			...args: Parameters<typeof page.evaluateHandle>
		) => {
			if (invalidateNextRead) {
				invalidateNextRead = false;
				failures++;
				throw new Error(
					"Execution context was destroyed, most likely because of a navigation",
				);
			}
			return originalRead(...args);
		}) as typeof page.evaluateHandle;
		let clicks = 0;
		const result = await runJev(
			{ goal: "Open" },
			{
				page: () => page,
				onStep: async (step) => {
					if (step.status === "executed") {
						clicks++;
						invalidateNextRead = true;
					}
				},
				policy: {
					async choose(data, _goal, history) {
						if (clicks) {
							assert.equal(data.targets[0]?.label, "Opened");
							assert.equal(history.length, 1);
							return { operation: "DONE" };
						}
						return { operation: "CLICK", target: data.targets[0] };
					},
					async text() {
						throw new Error("Unexpected text request");
					},
				},
			},
		);
		assert.equal(result.status, "done_unverified");
		assert.equal(clicks, 1);
		assert.equal(failures, 1);
		assert.equal(result.steps.length, 1);

		page.evaluateHandle = originalRead;
		await page.evaluate(() => {
			document.body.remove();
			setTimeout(() => {
				const body = document.createElement("body");
				body.innerHTML = "<h1>New document ready</h1>";
				document.documentElement.append(body);
			}, 150);
		});
		const settled = await observe(page);
		assert.match(settled.data.text, /New document ready/);
		await settled.dispose();

		let reads = 0;
		page.evaluateHandle = async () => {
			reads++;
			throw new Error("Execution context was destroyed");
		};
		await assert.rejects(observe(page), /Execution context/);
		assert.equal(reads, 5);
		reads = 0;
		page.evaluateHandle = async () => {
			reads++;
			throw new Error("Unexpected page bug");
		};
		await assert.rejects(observe(page), /Unexpected page bug/);
		assert.equal(reads, 1);
		const controller = new AbortController();
		controller.abort();
		await assert.rejects(observe(page, controller.signal), /abort/i);
		assert.equal(reads, 1);
	} finally {
		await browser.close();
	}
});

import assert from "node:assert/strict";
import { existsSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { createServer } from "node:http";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";

test("JSON IPC context supports wait batches and plugin-local cancellation", async () => {
	const directory = mkdtempSync(join(tmpdir(), "browser-ipc-"));
	const config = join(directory, "config.json");
	writeFileSync(
		config,
		JSON.stringify({ outputDir: directory, recordVideo: false }),
	);
	process.env.CLINE_JEV_BROWSER_CONFIG = config;
	const { JevBrowserManager } = await import("../src/runtime.ts");
	const manager = new JevBrowserManager();
	const server = createServer((_req, res) => res.end("<h1>Ready</h1>"));
	await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
	const address = server.address();
	if (!address || typeof address === "string")
		throw new Error("No test server address");
	const url = `http://127.0.0.1:${address.port}`;
	const context = JSON.parse(
		JSON.stringify({
			sessionId: "ipc-test",
			signal: new AbortController().signal,
		}),
	);
	assert.deepEqual(context.signal, {});
	try {
		const originalFetch = globalThis.fetch;
		const originalKey = process.env.AI_GATEWAY_API_KEY;
		process.env.AI_GATEWAY_API_KEY = "[REDACTED]";
		globalThis.fetch = async (_url, init) => {
			const { questions } = JSON.parse(String(init?.body));
			return Response.json({
				answers: Object.fromEntries(
					Object.entries(questions).map(([id, q]) => {
						const keys = Object.keys((q as { criteria: object }).criteria);
						const choice = id === "action" ? "DONE" : keys[0];
						return [
							id,
							{
								type: "choice",
								choice,
								probabilities: Object.fromEntries(
									keys.map((k) => [k, k === choice ? 1 : 0]),
								),
							},
						];
					}),
				),
			});
		};
		try {
			const run = await manager.run(
				{ goal: "Observe the Ready heading", url },
				context,
			);
			assert.equal(run.status, "done_unverified");
			assert.ok(existsSync(run.initialScreenshot.artifactPath));
			assert.ok(
				run.finalScreenshot && existsSync(run.finalScreenshot.artifactPath),
			);
			assert.ok(run.result?.some((block) => block.type === "image"));
			const second = await manager.run(
				{ goal: "Observe the Ready heading" },
				context,
			);
			assert.equal(
				second.initialScreenshot.state.startedAt,
				run.initialScreenshot.state.startedAt,
			);
			assert.notEqual(
				second.finalScreenshot?.artifactPath,
				run.finalScreenshot?.artifactPath,
			);
		} finally {
			globalThis.fetch = originalFetch;
			if (originalKey === undefined) delete process.env.AI_GATEWAY_API_KEY;
			else process.env.AI_GATEWAY_API_KEY = originalKey;
		}
		const waiting = manager.actions(
			{ actions: [{ type: "wait", ms: 30000 }], includeScreenshot: false },
			context,
		);
		const cancelled = assert.rejects(waiting, /abort/i);
		await assert.rejects(
			manager.actions({ actions: [{ type: "wait", ms: 1 }] }, context),
			/active/,
		);
		await manager.stop(context);
		await cancelled;
	} finally {
		await manager.stop(context);
		await new Promise<void>((resolve, reject) =>
			server.close((error) => (error ? reject(error) : resolve())),
		);
		rmSync(directory, { recursive: true, force: true });
	}
});

# Linear SDK recipes

Copy-paste building blocks for the canonical execution pattern in SKILL.md. Each snippet assumes:

```js
import { LinearClient } from "@linear/sdk"
const linear = new LinearClient({ apiKey: [REDACTED] })
```

Write the snippet into `"$LINEAR_DIR/task.mjs"` and run `node "$LINEAR_DIR/task.mjs"`.

## Resolve human inputs to IDs

Most mutations need UUIDs, but humans give you team keys, names, and emails. Look them up first.

```js
// Team by key (e.g. "ENG")
const teamConn = await linear.teams({ filter: { key: { eq: "ENG" } } })
const team = teamConn.nodes[0]

// User by email
const userConn = await linear.users({ filter: { email: { eq: "person@example.com" } } })
const user = userConn.nodes[0]

// Label by name within a team
const labels = await team.labels()
const bugLabel = labels.nodes.find((l) => l.name === "Bug")
```

## Find an issue by its human identifier (e.g. ENG-123)

`linear.issue(id)` expects a UUID. To resolve a human identifier, split it and filter:

```js
const identifier = "ENG-123"
const [key, numStr] = identifier.split("-")
const conn = await linear.issues({
  first: 1,
  filter: { team: { key: { eq: key } }, number: { eq: Number(numStr) } },
})
const issue = conn.nodes[0]
```

## List and filter issues

See the Filtering doc for the full comparator set. Common filters:

```js
// Open issues assigned to me, updated recently first
const me = await linear.viewer
const mine = await me.assignedIssues({
  first: 50,
  filter: { state: { type: { nin: ["completed", "canceled"] } } },
})

// Issues in a team with a given label
const byLabel = await linear.issues({
  first: 50,
  filter: { team: { key: { eq: "ENG" } }, labels: { name: { eq: "Bug" } } },
})

// Text search
const found = await linear.searchIssues("login crash")
```

Workflow state `type` values you can filter on: `backlog`, `unstarted`, `started`, `completed`, `canceled`, `triage`.

## Paginate through all results

Connections return one page at a time. Loop with `fetchNext`:

```js
const all = []
let page = await linear.issues({ first: 100, filter: { team: { key: { eq: "ENG" } } } })
all.push(...page.nodes)
while (page.pageInfo.hasNextPage) {
  page = await page.fetchNext()
  all.push(...page.nodes)
}
console.log(`fetched ${all.length} issues`)
```

## Read nested fields (async)

Relations are promises; await them.

```js
const issue = (await linear.issues({ first: 1 })).nodes[0]
const [state, assignee, team, comments] = await Promise.all([
  issue.state,
  issue.assignee,
  issue.team,
  issue.comments(),
])
console.log(issue.identifier, await state?.name, assignee ? assignee.displayName : "unassigned")
```

## Create an issue

```js
const team = (await linear.teams({ filter: { key: { eq: "ENG" } } })).nodes[0]
const payload = await linear.createIssue({
  teamId: team.id,
  title: "Fix flaky login test",
  description: "Repro steps...\n\n- one\n- two",
  // optional: assigneeId, priority (0-4), labelIds: [...], projectId, stateId
})
if (payload.success) {
  const created = await payload.issue
  console.log("created", created.identifier)
}
```

## Update an issue

```js
await linear.updateIssue("ISSUE_UUID", {
  title: "New title",
  assigneeId: "USER_UUID",
  priority: 2,
})
```

## Close (complete) or cancel an issue

There is no single "close" call. Set the issue's `stateId` to a workflow state whose `type` is `completed` (or `canceled`). States are per team.

```js
const issue = (await linear.issues({ first: 1, filter: { team: { key: { eq: "ENG" } }, number: { eq: 123 } } })).nodes[0]
const team = await issue.team
const states = await team.states()
const done = states.nodes.find((s) => s.type === "completed")
if (done) {
  await linear.updateIssue(issue.id, { stateId: done.id })
  console.log("closed", issue.identifier)
}
```

## Comment on an issue

```js
const payload = await linear.createComment({ issueId: "ISSUE_UUID", body: "Looking into this." })
if (payload.success) console.log("comment added")
```

## List teams, projects, cycles, users

```js
const teams = await linear.teams()
const projects = await linear.projects({ first: 50 })
const users = await linear.users()

// Cycles for a team
const team = teams.nodes[0]
const cycles = await team.cycles()
```

## Error handling

```js
try {
  // ... SDK calls ...
} catch (e) {
  const name = e?.constructor?.name
  if (e?.status === 401 || name === "AuthenticationLinearError") {
    console.error("AUTH_FAILED")
    process.exit(2)
  }
  if (e?.status === 429 || name === "RatelimitedLinearError") {
    console.error("RATE_LIMITED: back off and retry")
    process.exit(3)
  }
  console.error("LINEAR_ERROR:", name, e?.message)
  process.exit(1)
}
```

When a field, filter, or method name is uncertain, read the page noted in `docs-index.md` (Filtering, Pagination, SDK fetching and modifying data, or the GraphQL schema reference) and use the exact names from it.

